/*
 * pcspkr.c - OpenWindows PC Speaker Beep Driver (.owc)
 *
 * C99 freestanding. Zero dynamic heap allocation.
 *
 * The tone is generated by programming 8253/8254 channel 2 as a mode-3 square
 * wave and gating it onto the speaker through bits 0 and 1 of port 0x61.
 */

#include "pcspkr.h"

/* ── Port I/O helpers ─────────────────────────────────────────── */

static inline uint8_t pcspkr_inb(uint16_t port)
{
    uint8_t v;
    __asm__ __volatile__("inb %1, %0" : "=a"(v) : "Nd"(port));
    return v;
}

static inline void pcspkr_outb(uint16_t port, uint8_t value)
{
    __asm__ __volatile__("outb %0, %1" : : "a"(value), "Nd"(port));
}

/* ── Constants ────────────────────────────────────────────────── */

#define PCSPKR_PIT_MODE3    0xB6u   /* ch2, lo/hi, mode 3, binary        */
#define PCSPKR_GATE_BITS    0x03u   /* bit0 = timer gate, bit1 = speaker */

/* Nominal spin iterations per millisecond for the busy-wait helper. */
#define PCSPKR_SPIN_PER_MS  50000u

/* ── Internal state ───────────────────────────────────────────── */

static bool     pcspkr_initialized;
static uint32_t pcspkr_freq;

/* ── Helpers ──────────────────────────────────────────────────── */

/* Constrain a requested frequency to the audible range. */
static uint32_t pcspkr_clamp_freq(uint32_t frequency_hz)
{
    if (frequency_hz < PCSPKR_FREQ_MIN_HZ) {
        return PCSPKR_FREQ_MIN_HZ;
    }
    if (frequency_hz > PCSPKR_FREQ_MAX_HZ) {
        return PCSPKR_FREQ_MAX_HZ;
    }
    return frequency_hz;
}

/* Load channel 2 with the divisor that produces frequency_hz. */
static void pcspkr_program(uint32_t frequency_hz)
{
    uint32_t divisor = PCSPKR_PIT_BASE_HZ / frequency_hz;

    if (divisor < 1u) {
        divisor = 1u;
    }
    if (divisor > 0xFFFFu) {
        divisor = 0xFFFFu;
    }

    pcspkr_outb(PCSPKR_PIT_COMMAND, PCSPKR_PIT_MODE3);
    pcspkr_outb(PCSPKR_PIT_CH2_DATA, (uint8_t)(divisor & 0xFFu));
    pcspkr_outb(PCSPKR_PIT_CH2_DATA, (uint8_t)((divisor >> 8) & 0xFFu));
}

/* Gate the channel-2 square wave onto the speaker. */
static void pcspkr_enable(bool on)
{
    uint8_t value = pcspkr_inb(PCSPKR_CONTROL_PORT);

    if (on) {
        value = (uint8_t)(value | PCSPKR_GATE_BITS);
    } else {
        value = (uint8_t)(value & (uint8_t)(~PCSPKR_GATE_BITS));
    }
    pcspkr_outb(PCSPKR_CONTROL_PORT, value);
}

/* Coarse busy-wait; the exact rate is unimportant for a PC beep. */
static void pcspkr_spin_ms(uint32_t milliseconds)
{
    volatile uint64_t spins =
        ((uint64_t)milliseconds * (uint64_t)PCSPKR_SPIN_PER_MS) + 1u;

    while (spins != 0u) {
        --spins;
    }
}

/* ── Implementation ───────────────────────────────────────────── */

bool pcspkr_init(void)
{
    pcspkr_initialized = true;
    pcspkr_freq = 0u;
    pcspkr_enable(false);
    return true;
}

bool pcspkr_beep(uint32_t frequency_hz, uint32_t duration_ms)
{
    if (!pcspkr_initialized) {
        return false;
    }

    if (duration_ms > PCSPKR_DURATION_MAX) {
        duration_ms = PCSPKR_DURATION_MAX;
    }

    pcspkr_freq = pcspkr_clamp_freq(frequency_hz);
    pcspkr_program(pcspkr_freq);
    pcspkr_enable(true);
    pcspkr_spin_ms(duration_ms);
    pcspkr_enable(false);
    pcspkr_freq = 0u;
    return true;
}

bool pcspkr_set_freq(uint32_t frequency_hz)
{
    if (!pcspkr_initialized) {
        return false;
    }

    pcspkr_freq = pcspkr_clamp_freq(frequency_hz);
    pcspkr_program(pcspkr_freq);
    pcspkr_enable(true);
    return true;
}

bool pcspkr_stop(void)
{
    if (!pcspkr_initialized) {
        return false;
    }

    pcspkr_enable(false);
    pcspkr_freq = 0u;
    return true;
}

uint32_t pcspkr_get_freq(void)
{
    return pcspkr_freq;
}
